/* Native section surface and typography */
&.fdp-j-membership{padding:clamp(28px,5vw,76px) clamp(18px,5vw,72px);background:#f3eee5;color:#241c19;font-family:Arial,sans-serif;} &.fdp-j-membership h2{color:#241c19;line-height:1.06;letter-spacing:-.025em;font-size:clamp(32px,4.4vw,62px);} &.fdp-j-membership h3{color:#241c19;font-family:Arial,sans-serif;font-size:clamp(21px,2.1vw,30px);line-height:1.15;margin:0 0 14px;} &.fdp-j-membership p{color:#241c19;line-height:1.7;} &.fdp-j-membership .fdp-content{max-width:1160px;margin:24px auto 0;} &.fdp-j-membership .fdp-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;} &.fdp-j-membership .fdp-card{padding:clamp(22px,3vw,40px);background:#fffaf2;border:1px solid #a89e91;} &.fdp-j-membership .fdp-card p{margin-bottom:0;} &.fdp-j-membership .fdp-kicker{font-family:Arial,sans-serif;font-size:12px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;margin:0 0 18px;} &.fdp-j-membership .fdp-action{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:48px;padding:14px 24px;background:#a94728;color:#fffaf1;font:700 13px/1.3 Arial,sans-serif;letter-spacing:.06em;text-decoration:none;} &.fdp-j-membership .fdp-action:focus-visible{outline:3px solid #241c19;outline-offset:4px;} &.fdp-j-membership .fdp-action:hover{text-decoration:underline;} &.fdp-j-membership .fdp-actions{margin:28px 0 0;} &.fdp-j-membership .fdp-number{display:block;color:#a94728;font:700 13px/1.2 Arial,sans-serif;letter-spacing:.15em;margin-bottom:20px;} &.fdp-j-membership .fdp-list{margin:0;padding:0;list-style:none;} &.fdp-j-membership .fdp-list li{padding:16px 0;border-bottom:1px solid #a89e91;line-height:1.6;} @media(max-width:720px){&.fdp-j-membership .fdp-grid{grid-template-columns:1fr;} &.fdp-j-membership .fdp-card{padding:24px;} &.fdp-j-membership .fdp-action{width:100%;box-sizing:border-box;}} &.fdp-j-membership h2{font-weight:900;font-size:clamp(30px,4vw,52px);}&.fdp-j-membership .fdp-ticket{display:grid;grid-template-columns:2fr 1fr;border:2px solid #241c19;background:#fffaf2;}&.fdp-j-membership .fdp-ticket-main,&.fdp-j-membership .fdp-ticket-stub{padding:clamp(24px,4vw,46px);}&.fdp-j-membership .fdp-ticket-stub{border-left:2px dashed #a89e91;display:flex;flex-direction:column;align-items:flex-start;justify-content:space-between;gap:20px;background:#ece1d0;}&.fdp-j-membership .fdp-list li:last-child{border-bottom:0;}@media(max-width:720px){&.fdp-j-membership .fdp-ticket{grid-template-columns:1fr;}&.fdp-j-membership .fdp-ticket-stub{border-left:0;border-top:2px dashed #a89e91;}}
/* Keep content within the section on narrow screens */
&.fdp-j-membership,&.fdp-j-membership *{box-sizing:border-box;}&.fdp-j-membership .fdp-content,&.fdp-j-membership .fdp-content>*,&.fdp-j-membership .fdp-content article,&.fdp-j-membership .fdp-content aside{min-width:0;}&.fdp-j-membership p,&.fdp-j-membership li,&.fdp-j-membership a{overflow-wrap:break-word;}
&.fdp-j-membership{background:#f3eee5!important;} &.fdp-j-membership h2{color:#241c19!important;}
